/* Cyberpunk Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Cyberpunk Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 248 248 248;
    --foreground: 11 10 30;
    --card: 255 255 255;
    --card-foreground: 11 10 30;
    --popover: 255 255 255;
    --popover-foreground: 11 10 30;
    --primary: 254 0 199;
    --primary-foreground: 255 255 255;
    --secondary: 240 240 255;
    --secondary-foreground: 11 10 30;
    --muted: 240 240 255;
    --muted-foreground: 11 10 30;
    --accent: 32 254 204;
    --accent-foreground: 11 10 30;
    --destructive: 252 63 9;
    --destructive-foreground: 255 255 255;
    --border: 222 230 234;
    --input: 222 230 234;
    --ring: 254 0 199;
    --chart-1: 254 0 199;
    --chart-2: 144 13 253;
    --chart-3: 0 228 253;
    --chart-4: 32 254 204;
    --chart-5: 255 231 41;
    --radius: 0.5rem;
    --sidebar: 240 240 255;
    --sidebar-foreground: 11 10 30;
    --sidebar-primary: 254 0 199;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 32 254 204;
    --sidebar-accent-foreground: 11 10 30;
    --sidebar-border: 222 230 234;
    --sidebar-ring: 254 0 199;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Fira Code, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 11 10 30;
    --foreground: 235 239 245;
    --card: 29 29 61;
    --card-foreground: 235 239 245;
    --popover: 29 29 61;
    --popover-foreground: 235 239 245;
    --primary: 254 0 199;
    --primary-foreground: 255 255 255;
    --secondary: 29 29 61;
    --secondary-foreground: 235 239 245;
    --muted: 29 29 61;
    --muted-foreground: 127 132 165;
    --accent: 32 254 204;
    --accent-foreground: 11 10 30;
    --destructive: 252 63 9;
    --destructive-foreground: 255 255 255;
    --border: 47 47 93;
    --input: 47 47 93;
    --ring: 254 0 199;
    --chart-1: 254 0 199;
    --chart-2: 144 13 253;
    --chart-3: 0 228 253;
    --chart-4: 32 254 204;
    --chart-5: 255 231 41;
    --radius: 0.5rem;
    --sidebar: 11 10 30;
    --sidebar-foreground: 235 239 245;
    --sidebar-primary: 254 0 199;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 32 254 204;
    --sidebar-accent-foreground: 11 10 30;
    --sidebar-border: 47 47 93;
    --sidebar-ring: 254 0 199;
    --font-sans: Outfit, sans-serif;
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: Fira Code, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -2px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -2px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -2px hsl(0 0% 0% / 0.25);
  }

}
